# Statistics and Mechanics Year 1, Chapter 1: data collection (the numerical parts).
def strat(qid, groups, n, want): check(qid, [round(g * n / sum(groups) + 1e-9) for g in groups], want, 0)
check('A1.2-1', 800 / 40, 20, 0); strat('A1.2-3', [60, 40], 20, [12, 8]); strat('A1.2-4', [150, 250, 100], 40, [12, 20, 8])
check('A1.2-8', [123 * 50 / 500, 245 * 50 / 500, 132 * 50 / 500], [12.3, 24.5, 13.2], 1e-9); check('A1.2-8t', 12 + 25 + 13, 50, 0)
strat('A1.2-11', [120, 80, 40, 160], 60, [18, 12, 6, 24]); check('A1.2-14', [17 + 30 * i for i in (0, 1, 2, 29)], [17, 47, 77, 887], 0)
strat('A1.2-15', [480, 360, 160], 50, [24, 18, 8]); check('A1.3-15', [120 * r / 12 for r in (5, 4, 3)], [50, 40, 30], 0)
check('A1.4-4', [(14.5 + 19.5) / 2, 19.5 - 14.5], [17, 5], 0); check('A1.4-12', [159.5 - 149.5, 164.5 - 159.5, 179.5 - 164.5], [10, 5, 15], 0)
check('A1.4-14', (8 * 2.5 + 12 * 7.5 + 6 * 15) / 26, 7.69, 0.006); check('A1.4-15', (14 * 14.5 + 25 * 24.5 + 9 * 37) / 48, 23.9, 0.05)
check('A1.5-9', [184 / 20, 9 + 9 * 19 <= 184], [9.2, True], 1e-9)
